ALTER TABLE public.lrs ADD COLUMN transporter_freight_direction text NOT NULL DEFAULT 'payable' CHECK(transporter_freight_direction IN('payable','receivable'));
CREATE TABLE public.driver_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),trip_id uuid REFERENCES public.trips(id),driver_id uuid NOT NULL REFERENCES public.drivers(id),party_id uuid REFERENCES public.parties(id),kind text NOT NULL CHECK(kind IN('party_receipt','expense')),amount numeric NOT NULL CHECK(amount>0 AND amount=round(amount,2)),entry_date date NOT NULL,payment_method text,account_id uuid REFERENCES public.payment_accounts(id),reference text,notes text,is_cancelled boolean NOT NULL DEFAULT false,cancel_reason text,created_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(kind<>'party_receipt' OR(party_id IS NOT NULL AND account_id IS NULL)));
GRANT SELECT,INSERT,UPDATE ON public.driver_transactions TO authenticated; GRANT ALL ON public.driver_transactions TO service_role;
ALTER TABLE public.driver_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_member ON public.driver_transactions FOR SELECT TO authenticated USING(public.is_business_member(business_id)); CREATE POLICY insert_member ON public.driver_transactions FOR INSERT TO authenticated WITH CHECK(public.is_business_member(business_id)); CREATE POLICY update_member ON public.driver_transactions FOR UPDATE TO authenticated USING(public.is_business_member(business_id)) WITH CHECK(public.is_business_member(business_id));
CREATE INDEX driver_transactions_trip ON public.driver_transactions(trip_id); CREATE INDEX driver_transactions_driver_date ON public.driver_transactions(driver_id,entry_date);
CREATE TRIGGER a_stamp_business BEFORE INSERT OR UPDATE ON public.driver_transactions FOR EACH ROW EXECUTE FUNCTION public.stamp_business_id(); CREATE TRIGGER z_audit AFTER INSERT OR UPDATE ON public.driver_transactions FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE FUNCTION public.driver_transaction_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_OP='UPDATE' AND OLD.is_cancelled THEN RAISE EXCEPTION 'Cancelled entry cannot be edited'; END IF;
 IF NEW.is_cancelled AND nullif(trim(NEW.cancel_reason),'') IS NULL THEN RAISE EXCEPTION 'Cancellation reason required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.drivers WHERE id=NEW.driver_id AND business_id=NEW.business_id) OR(NEW.party_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.parties WHERE id=NEW.party_id AND business_id=NEW.business_id)) OR(NEW.account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.payment_accounts WHERE id=NEW.account_id AND business_id=NEW.business_id)) OR(NEW.trip_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.trips WHERE id=NEW.trip_id AND business_id=NEW.business_id AND(status<>'cancelled' OR NEW.is_cancelled))) THEN RAISE EXCEPTION 'Driver, party, trip or account unavailable in your business'; END IF;
 NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER b_driver_guard BEFORE INSERT OR UPDATE ON public.driver_transactions FOR EACH ROW EXECUTE FUNCTION public.driver_transaction_guard();
CREATE FUNCTION public.driver_transaction_after() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.ledger_entries; BEGIN
 IF NEW.is_cancelled THEN FOR l IN SELECT * FROM public.ledger_entries WHERE source_table='driver_transactions' AND source_id=NEW.id AND reversal_of IS NULL AND line_kind NOT LIKE '%_reversal' LOOP
 PERFORM public.post_ledger(NEW.business_id,l.account_type,l.account_id,'driver_transactions',NEW.id,l.line_kind||'_reversal',(now() AT TIME ZONE 'Asia/Kolkata')::date,'Reversal: '||NEW.cancel_reason,l.credit,l.debit);
 UPDATE public.ledger_entries SET reversal_of=l.id WHERE source_table='driver_transactions' AND source_id=NEW.id AND line_kind=l.line_kind||'_reversal'; END LOOP; RETURN NEW; END IF;
 PERFORM public.ledger_set(NEW.business_id,'driver',NEW.driver_id,'driver_transactions',NEW.id,'driver',NEW.entry_date,CASE WHEN NEW.kind='party_receipt' THEN 'Received directly from '||(SELECT name FROM public.parties WHERE id=NEW.party_id) ELSE 'Driver expenses: '||coalesce(NEW.notes,'') END,CASE WHEN NEW.kind='party_receipt' THEN NEW.amount ELSE 0 END,CASE WHEN NEW.kind='expense' THEN NEW.amount ELSE 0 END);
 PERFORM public.ledger_set(NEW.business_id,'party',CASE WHEN NEW.kind='party_receipt' THEN NEW.party_id END,'driver_transactions',NEW.id,'party',NEW.entry_date,'Paid directly to driver',0,CASE WHEN NEW.kind='party_receipt' THEN NEW.amount ELSE 0 END);
 PERFORM public.ledger_set(NEW.business_id,'driver',CASE WHEN NEW.kind='expense' AND NEW.account_id IS NOT NULL THEN NEW.driver_id END,'driver_transactions',NEW.id,'reimbursement',NEW.entry_date,'Driver expense reimbursed',CASE WHEN NEW.kind='expense' AND NEW.account_id IS NOT NULL THEN NEW.amount ELSE 0 END,0); RETURN NEW; END $$;
CREATE TRIGGER c_driver_after AFTER INSERT OR UPDATE ON public.driver_transactions FOR EACH ROW EXECUTE FUNCTION public.driver_transaction_after();
CREATE FUNCTION public.save_driver_transaction(p jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v_id uuid:=(p->>'id')::uuid; v_biz uuid:=public.current_business_id(); oldrow public.driver_transactions; BEGIN
 IF auth.uid() IS NULL OR v_biz IS NULL THEN RAISE EXCEPTION 'Business access required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(v_id::text,0));
 SELECT * INTO oldrow FROM public.driver_transactions WHERE id=v_id FOR UPDATE;
 IF FOUND AND(oldrow.business_id<>v_biz OR oldrow.is_cancelled) THEN RAISE EXCEPTION 'Entry unavailable or access denied'; END IF;
 IF coalesce((p->>'cancel')::boolean,false) THEN UPDATE public.driver_transactions SET is_cancelled=true,cancel_reason=p->>'cancel_reason' WHERE id=v_id AND business_id=v_biz; RETURN v_id; END IF;
 INSERT INTO public.driver_transactions(id,trip_id,driver_id,party_id,kind,amount,entry_date,payment_method,account_id,reference,notes) VALUES(v_id,nullif(p->>'trip_id','')::uuid,(p->>'driver_id')::uuid,nullif(p->>'party_id','')::uuid,p->>'kind',(p->>'amount')::numeric,(p->>'entry_date')::date,p->>'payment_method',nullif(p->>'account_id','')::uuid,p->>'reference',p->>'notes') ON CONFLICT(id) DO UPDATE SET driver_id=EXCLUDED.driver_id,party_id=EXCLUDED.party_id,kind=EXCLUDED.kind,amount=EXCLUDED.amount,entry_date=EXCLUDED.entry_date,payment_method=EXCLUDED.payment_method,account_id=EXCLUDED.account_id,reference=EXCLUDED.reference,notes=EXCLUDED.notes WHERE driver_transactions.business_id=v_biz AND driver_transactions.trip_id IS NOT DISTINCT FROM EXCLUDED.trip_id; IF NOT FOUND THEN RAISE EXCEPTION 'Entry belongs to another trip'; END IF; RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.save_driver_transaction(jsonb),public.driver_transaction_guard(),public.driver_transaction_after() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_driver_transaction(jsonb),public.driver_transaction_guard(),public.driver_transaction_after() TO authenticated,service_role;
CREATE FUNCTION public.cancel_trip_driver_transactions() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='cancelled' AND OLD.status<>'cancelled' THEN UPDATE public.driver_transactions SET is_cancelled=true,cancel_reason=NEW.cancel_reason WHERE trip_id=NEW.id AND NOT is_cancelled; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.cancel_trip_driver_transactions() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cancel_trip_driver_transactions() TO authenticated,service_role;
CREATE TRIGGER d_cancel_driver_transactions AFTER UPDATE ON public.trips FOR EACH ROW EXECUTE FUNCTION public.cancel_trip_driver_transactions();
DO $$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.save_trip(jsonb)'::regprocedure);
 d:=replace(d,' RETURN v_id;', ' IF p ? ''driver_transactions'' THEN FOR r IN SELECT * FROM jsonb_array_elements(p->''driver_transactions'') LOOP PERFORM public.save_driver_transaction(r || jsonb_build_object(''trip_id'',v_id)); END LOOP; END IF; RETURN v_id;'); EXECUTE d;
 d:=pg_get_functiondef('public.save_lr(jsonb)'::regprocedure); d:=replace(d,'UPDATE public.lrs SET transporter_freight_date=', 'UPDATE public.lrs SET transporter_freight_direction=CASE WHEN p ? ''transporter_freight_direction'' THEN p->>''transporter_freight_direction'' ELSE transporter_freight_direction END,transporter_freight_date='); EXECUTE d;
 d:=pg_get_functiondef('public.lr_after()'::regprocedure); d:=replace(d,$s$'Freight payable '||v_label,0,CASE WHEN v_active THEN NEW.freight_payable ELSE 0 END$s$,$s$CASE WHEN NEW.transporter_freight_direction='receivable' THEN 'Freight receivable ' ELSE 'Freight payable ' END||v_label,CASE WHEN v_active AND NEW.transporter_freight_direction='receivable' THEN NEW.freight_payable ELSE 0 END,CASE WHEN v_active AND NEW.transporter_freight_direction='payable' THEN NEW.freight_payable ELSE 0 END$s$); EXECUTE d;
 d:='CREATE OR REPLACE VIEW public.account_movements WITH(security_invoker=true) AS '||pg_get_viewdef('public.account_movements'::regclass,true); d:=rtrim(d,E';\n ')||' UNION ALL SELECT business_id,account_id,entry_date,created_at,''driver_transactions''::text,id,''driver_expense''::text,''out''::text,amount,reference,notes,NULL::uuid,NULL::uuid,driver_id,NULL::text FROM public.driver_transactions WHERE kind=''expense'' AND account_id IS NOT NULL AND NOT is_cancelled'; EXECUTE d;
 END $$;